/* Generated by port_site.py from the approved mockup. Behaviour for the journey section; timers, listeners and observers go through ctx. */
export function init(ctx) {
  var reduce = ctx.reduce,
    root = document.documentElement;

  /* section 2: walk one guest through the stages */
  var S2 = [
    [
      "Enquiry",
      "A guest finds you on a reel at 2 AM and writes in. HAIP answers in seconds and notes where they came from.",
      "Enquiry",
      ["#DDF0E8", "#0E4A36"],
    ],
    [
      "Lead",
      "The moment they share a number, they become a lead with an owner. Your team sees them first thing.",
      "Active",
      ["#E8E0FF", "#4B2AA8"],
    ],
    [
      "Quote",
      "Your team sends the quote from the same record, and HAIP reminds them to follow up.",
      "Quoted",
      ["#FFF0CC", "#7A5206"],
    ],
    [
      "Paid",
      "The Razorpay advance lands, the dates are held on every channel, and nobody has to check twice.",
      "Sold",
      ["#E2E6FF", "#2B3596"],
    ],
    [
      "Stay",
      "They check in, add a bonfire, and the revenue is traced back to the reel that brought them.",
      "Stayed",
      ["#FBF1D6", "#5A3F06"],
    ],
  ];
  var s2steps = [].slice.call(document.querySelectorAll(".step")),
    s2items = [].slice.call(document.querySelectorAll("#s2tl li")),
    s2fill = document.querySelector(".steps .fill"),
    s2txt = document.getElementById("s2txt"),
    s2i = 0,
    s2auto = true,
    s2tm = null;
  function s2show(i, user) {
    var prev = s2i;
    s2i = i;
    s2steps.forEach(function (b, j) {
      b.setAttribute("aria-selected", String(j === i));
      b.tabIndex = j === i ? 0 : -1;
      b.classList.toggle("done", j < i);
    });
    s2fill.style.setProperty("--p", i / (s2steps.length - 1));
    s2items.forEach(function (li, j) {
      li.classList.toggle("wait", j > i);
      li.classList.remove("now");
      if (j === i && i >= prev && !reduce) {
        void li.offsetWidth;
        li.classList.add("now");
      }
    });
    var pill = document.getElementById("s2pill");
    pill.textContent = S2[i][2];
    pill.style.background = S2[i][3][0];
    pill.style.color = S2[i][3][1];
    document.getElementById("s2roi").classList.toggle("hide", i < 4);
    s2txt.classList.add("swap");
    ctx.setTimeout(
      function () {
        document.getElementById("s2name").textContent = S2[i][0];
        document.getElementById("s2copy").textContent = S2[i][1];
        s2txt.classList.remove("swap");
      },
      reduce ? 0 : 200,
    );
    if (user) {
      s2auto = false;
      ctx.clearTimeout(s2tm);
    }
  }
  function s2cycle() {
    if (!s2auto || reduce || document.hidden) {
      s2tm = null;
      return;
    }
    s2tm = ctx.setTimeout(
      function () {
        s2show((s2i + 1) % S2.length);
        s2cycle();
      },
      s2i === 4 ? 4000 : 2600,
    );
  }
  s2steps.forEach(function (b, i) {
    ctx.on(b, "click", function () {
      s2show(i, true);
    });
    ctx.on(b, "keydown", function (e) {
      var d = e.key === "ArrowRight" ? 1 : e.key === "ArrowLeft" ? -1 : 0;
      if (d) {
        e.preventDefault();
        var n = (i + d + s2steps.length) % s2steps.length;
        s2show(n, true);
        s2steps[n].focus();
      }
    });
  });
  ctx.on(document, "visibilitychange", function () {
    if (!document.hidden && !s2tm) s2cycle();
  });
  // Opens on the last stage so the whole record is visible at rest, then walks from the start.
  s2show(4);
  document.getElementById("s2copy").textContent = S2[4][1];
  document.getElementById("s2name").textContent = S2[4][0];
  if (!reduce)
    s2tm = ctx.setTimeout(function () {
      s2show(0);
      s2cycle();
    }, 2400);
}
